// src/Dashboard.jsx
import React, { useEffect, useState } from "react";
import "./CSS/Dashboard.css";
import { useNavigate } from "react-router-dom";

function Dashboard() {
  const [messages, setMessages] = useState([]);
  const [search, setSearch] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    fetch("http://127.0.0.1:5000/get-messages")
      .then((res) => res.json())
      .then((data) => {
        if (data.success) setMessages(data.messages);
      })
      .catch((err) => console.error("Error fetching messages", err));
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  const filteredMessages = messages.filter(
    (msg) =>
      msg.sender.toLowerCase().includes(search.toLowerCase()) ||
      msg.receiver.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <input
          type="text"
          className="dashboard-search"
          placeholder="Search by sender/receiver"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button className="dashboard-logout" onClick={handleLogout}>
          Logout
        </button>
      </header>

      <main className="dashboard-content">
        <h2>View Messages Of Users</h2>
        <div className="message-list">
          {filteredMessages.length > 0 ? (
            filteredMessages.map((msg, idx) => (
              <div key={idx} className="message-card">
                <p><strong>From:</strong> {msg.sender}</p>
                <p><strong>To:</strong> {msg.receiver}</p>
                <p><strong>Time:</strong> {msg.timestamp}</p>
                <p><strong>Encrypted Message:</strong> {msg.encrypted_message}</p>
              </div>
            ))
          ) : (
            <p className="no-messages">No messages found.</p>
          )}
        </div>
      </main>
    </div>
  );
}

export default Dashboard;
